        { x: 29.08, y: 88.0, name: 'GPT-5 (high)', family: '#10B981' },
        { x: 17.69, y: 86.7, name: 'GPT-5 (med)', family: '#10B981' },
        { x: 22.14, y: 85.3, name: 'Claude 4.0 Opus', family: '#D97706' },
        { x: 9.47, y: 84.0, name: 'Claude 4.0 Sonnet', family: '#D97706' },
        { x: 4.92, y: 82.7, name: 'Gemini 2.5 Pro', family: '#3B82F6' },
        { x: 18.35, y: 82.2, name: 'o3 (high)', family: '#10B981' },
        { x: 8.12, y: 81.3, name: 'GPT-5 (low)', family: '#10B981' },
        { x: 3.88, y: 80.4, name: 'DeepSeek R1', family: '#8B5CF6' },
        { x: 7.81, y: 79.6, name: 'Claude 3.7 Sonnet', family: '#D97706' },
        { x: 10.22, y: 78.7, name: 'o3 (med)', family: '#10B981' },
        { x: 1.28, y: 76.4, name: 'Gemini 2.5 Flash', family: '#3B82F6' },
        { x: 5.60, y: 74.7, name: 'GPT-4.1', family: '#10B981' },
        { x: 1.95, y: 72.9, name: 'DeepSeek V3', family: '#8B5CF6' },
        { x: 6.33, y: 72.0, name: 'Claude 3.5 Sonnet', family: '#D97706' },
        { x: 4.47, y: 71.1, name: 'o4-mini', family: '#10B981' }
      ];

      var datasets = modelsData.map(function(m) {
        return {
          label: m.name,
          data: [{x: m.x, y: m.y}],
          backgroundColor: m.family,
          borderColor: '#ffffff',
          borderWidth: 1,
          pointRadius: 8,
          pointHoverRadius: 10
        };
      });

      new Chart(ctx, {
        type: 'scatter',
        data: { datasets: datasets },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var m = modelsData[ctx.datasetIndex];
                  return m.name + ': ' + m.y + '% at $' + m.x;
                }
              },
              backgroundColor: 'rgba(15, 23, 42, 0.9)',
              titleFont: { size: 16, family: 'Inter' },
              bodyFont: { size: 14, family: 'Inter' },
              padding: 12,
              cornerRadius: 8
            }
          },
          scales: {
            x: {
              title: { display: true, text: 'Cost per Run ($)', color: '#94A3B8', font: { size: 16, family: 'Inter', weight: 600 } },
              grid: { color: 'rgba(255,255,255,0.05)' },
              ticks: { color: '#94A3B8', font: { size: 14 }, callback: function(value) { return '$' + value; } },
              min: 0, max: 35
            },
            y: {
              title: { display: true, text: 'Accuracy (%)', color: '#94A3B8', font: { size: 16, family: 'Inter', weight: 600 } },
              grid: { color: 'rgba(255,255,255,0.05)' },
              ticks: { color: '#94A3B8', font: { size: 14 }, callback: function(value) { return value + '%'; } },
              min: 70, max: 90
            }
          }
        },
        plugins: [{
          id: 'textLabels',
          afterDatasetsDraw: function(chart) {
            var ctx = chart.ctx;
            ctx.font = '500 13px Inter';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';

            // Draw labels for key points
            chart.data.datasets.forEach(function(ds, i) {
              var meta = chart.getDatasetMeta(i);
              var pt = meta.data[0];
              var m = modelsData[i];

              if (['GPT-5 (high)', 'Claude 4.0 Opus', 'Gemini 2.5 Flash', 'DeepSeek R1', 'Claude 4.0 Sonnet', 'Gemini 2.5 Pro'].includes(m.name)) {
                ctx.fillStyle = '#F8FAFC';

                var xOff = 12;
                var yOff = 0;

                // Adjust positions to prevent overlap
                if (m.name === 'Claude 4.0 Opus') yOff = 8;
                if (m.name === 'DeepSeek R1') { yOff = -12; xOff = -40; ctx.textAlign = 'right'; }
                if (m.name === 'Gemini 2.5 Flash') { yOff = -12; xOff = -40; ctx.textAlign = 'right'; }
                if (m.name === 'Gemini 2.5 Pro') { yOff = -12; xOff = -40; ctx.textAlign = 'right'; }

                ctx.fillText(m.name, pt.x + xOff, pt.y + yOff);
                ctx.textAlign = 'left'; // reset
              }
            });
          }
        }]
      });
    });
  </script>
</body>
</html>
