    /* Layout Sections */
    .poster-header { padding: 48px 64px 32px; border-bottom: 1px solid var(--border); }
    .poster-body { flex: 1; display: flex; flex-direction: column; gap: 40px; padding: 48px 64px; justify-content: space-between; }
