    .metric-context { font-size: 14px; color: var(--text-secondary); opacity: 0.8; }

    /* Ranking Table */
    .table-container { background: var(--surface); border-radius: 20px; border: 1px solid var(--border); overflow: hidden; backdrop-filter: blur(12px); box-shadow: 0 24px 48px rgba(0,0,0,0.4); }
    table { width: 100%; border-collapse: collapse; text-align: left; }
    th { padding: 20px 24px; font-size: 16px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-secondary); border-bottom: 1px solid var(--border); background: rgba(0,0,0,0.2); }
