    .badge { display: inline-block; padding: 4px 12px; border-radius: 99px; font-size: 14px; font-weight: 600; letter-spacing: 0.02em; }
    .badge-openai { background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3); }
    .badge-anthropic { background: rgba(217, 119, 6, 0.15); color: #d97706; border: 1px solid rgba(217, 119, 6, 0.3); }
