  <script>
    function toggleMenu() { 
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open'); 
    }
    document.addEventListener('click', function(e) { 
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = 'aider-leaderboard.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    Chart.defaults.animation = false;
    var chartsBuilt = false;

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;
      var isDark = document.documentElement.classList.contains('theme-dark');
      var gridColor = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)';
      var textColor = isDark ? '#94A3B8' : '#64748b';

      var modelsData = [
        { x: 29.08, y: 88.0, name: 'GPT-5 (H)', family: '#10b981' },
        { x: 17.69, y: 86.7, name: 'GPT-5 (M)', family: '#10b981' },
        { x: 22.14, y: 85.3, name: 'Claude 4.0 Opus', family: '#d97706' },
        { x: 9.47, y: 84.0, name: 'Claude 4.0 Sonnet', family: '#d97706' },
        { x: 4.92, y: 82.7, name: 'Gemini 2.5 Pro', family: '#3b82f6' },
        { x: 18.35, y: 82.2, name: 'o3 (H)', family: '#10b981' },
        { x: 8.12, y: 81.3, name: 'GPT-5 (L)', family: '#10b981' },
        { x: 3.88, y: 80.4, name: 'DeepSeek R1', family: '#8b5cf6' },
        { x: 7.81, y: 79.6, name: 'Claude 3.7', family: '#d97706' },
        { x: 10.22, y: 78.7, name: 'o3 (M)', family: '#10b981' },
        { x: 1.28, y: 76.4, name: 'Gemini Flash', family: '#3b82f6' },
        { x: 5.60, y: 74.7, name: 'GPT-4.1', family: '#10b981' },
        { x: 1.95, y: 72.9, name: 'DeepSeek V3', family: '#8b5cf6' },
        { x: 6.33, y: 72.0, name: 'Claude 3.5', family: '#d97706' },
        { x: 4.47, y: 71.1, name: 'o4-mini', family: '#10b981' }
      ];

      var datasets = modelsData.map(function(m) {
        return {
          label: m.name,
          data: [{x: m.x, y: m.y}],
          backgroundColor: m.family,
          borderColor: isDark ? '#000' : '#fff',
          borderWidth: 1,
          pointRadius: 7,
          pointHoverRadius: 9
        };
      });

      var ctx = resetCanvas('costAccuracyChart');
      if (ctx) {
        window.myChart = new Chart(ctx, {
          type: 'scatter',
          data: { datasets: datasets },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: { display: false },
              tooltip: {
                enabled: true,
                callbacks: {
                  label: function(c) {
                    var m = modelsData[c.datasetIndex];
                    return m.name + ': ' + m.y + '% at $' + m.x;
                  }
                },
                padding: 12, cornerRadius: 8
              }
            },
            scales: {
              x: {
                title: { display: true, text: 'Cost per Run ($)', color: textColor, font: { family: 'Inter', weight: 600 } },
                grid: { color: gridColor },
                ticks: { color: textColor, callback: function(val) { return '$' + val; } }
              },
              y: {
                title: { display: true, text: 'Accuracy (%)', color: textColor, font: { family: 'Inter', weight: 600 } },
                grid: { color: gridColor },
                ticks: { color: textColor, callback: function(val) { return val + '%'; } }
              }
            }
          },
          plugins: [{
            id: 'textLabels',
            afterDatasetsDraw: function(chart) {
              var c = chart.ctx;
              c.font = '500 12px Inter';
              c.textAlign = 'left';
              c.textBaseline = 'middle';

              chart.data.datasets.forEach(function(ds, i) {
                var meta = chart.getDatasetMeta(i);
                var pt = meta.data[0];
                var m = modelsData[i];

                var topModels = ['GPT-5 (H)', 'Claude 4.0 Opus', 'Gemini Flash', 'DeepSeek R1', 'Claude 4.0 Sonnet', 'Gemini 2.5 Pro'];
                if (topModels.includes(m.name)) {
                  c.fillStyle = isDark ? '#F8FAFC' : '#0f172a';
                  var xOff = 10, yOff = 0;
                  if (m.name === 'Claude 4.0 Opus') yOff = -12;
                  if (m.name === 'DeepSeek R1' || m.name === 'Gemini Flash' || m.name === 'Gemini 2.5 Pro') { 
                    xOff = -10; c.textAlign = 'right'; 
                    if (m.name === 'DeepSeek R1') yOff = 12;
                  }
                  c.fillText(m.name, pt.x + xOff, pt.y + yOff);
                  c.textAlign = 'left';
                }
              });
            }
          }]
        });
      }
      chartsBuilt = true;
    }

    function onThemeChange() { chartsBuilt = false; setTimeout(buildCharts, 50); }
    document.addEventListener('DOMContentLoaded', buildCharts);

  </script>
